import{_ as e,o,c as n,ah as a}from"./chunks/framework.D4KxWb5R.js";const p=JSON.parse('{"title":"Registry: products and zones","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/administration/registry.md","filePath":"src/en/guide/administration/registry.md"}'),r={name:"en/guide/administration/registry.md"};function i(s,t,d,c,h,l){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="registry-products-and-zones" tabindex="-1">Registry: products and zones <a class="header-anchor" href="#registry-products-and-zones" aria-label="Permalink to &quot;Registry: products and zones&quot;">​</a></h1><p>The registry lists M&#39;City&#39;s products and the zones where they operate. It feeds the site&#39;s landing pages, the &quot;Our zones&quot; page and the intranet&#39;s product spaces. <strong>Products</strong> and <strong>Zones</strong> are open to the CEO and to Product Operations; a product&#39;s technical integration is for the CEO only.</p><p>Nothing is deleted: an inactive product or zone goes offline and keeps its history.</p><h2 id="zones" tabindex="-1">Zones <a class="header-anchor" href="#zones" aria-label="Permalink to &quot;Zones&quot;">​</a></h2><p>Qualifying a zone <strong>records a decision</strong> M&#39;City made outside the platform, at the end of the zone assessment. The platform neither checks nor computes anything, and never stores the assessment itself.</p><ol><li><strong>Zones → New zone</strong> (or open a zone).</li><li>Enter the <strong>name</strong> and <strong>region</strong>.</li><li>For a qualified zone: set <strong>Qualification</strong> to <strong>Qualified</strong>, then choose the <strong>zone type</strong> (growing city, structured city, peri-urban area) and enter the <strong>public description</strong>, at least in English.</li><li>Optionally add a photo (JPG, PNG or WebP, 2 MB at most), shown at the top of the zone&#39;s card on the site.</li><li>Save.</li></ol><p>A qualified, active zone appears on &quot;Our zones&quot; and can be attached to a product. An <strong>inactive</strong> zone is hidden from the site.</p><p>A zone attached to an active product can be neither unqualified nor disabled: detach it from the product first.</p><h2 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h2><h3 id="registering-a-product" tabindex="-1">Registering a product <a class="header-anchor" href="#registering-a-product" aria-label="Permalink to &quot;Registering a product&quot;">​</a></h3><ol><li><strong>Products → New product</strong>.</li><li><strong>Identity</strong>: name, URL slug (the landing page will be at <code>/products/&lt;slug&gt;</code>), status, logo (PNG, JPG or WebP, 2 MB at most), primary and secondary colours, access link (app or site), back-office address, the languages the product supports (ISO codes separated by commas, e.g. <code>en, fr, pt</code>).</li><li><strong>Landing page content</strong>, in English and French: tagline, presentation, &quot;Who is it for?&quot;, key features, &quot;How it works&quot; steps, the product&#39;s own contact, legal notice.</li><li><strong>Visuals</strong>: add the landing page images (PNG, JPG or WebP, 5 MB at most each).</li><li><strong>Zones</strong>: tick the zones where the product operates. Only qualified, active zones are offered.</li><li><strong>Responsible teams</strong>: tick the product&#39;s <a href="./teams.html">teams</a>.</li><li><strong>Create product</strong>.</li></ol><p>Saving creates the landing page on the public site and the product&#39;s space in the intranet automatically.</p><ul><li>An <strong>Active (online)</strong> product needs at least its English tagline.</li><li>An <strong>Inactive (offline)</strong> product may stay incomplete; its landing page is no longer published.</li><li>The back-office address is never shown on the public site: it is used by the intranet&#39;s <strong>Open the back-office</strong> button.</li></ul><h3 id="editing-a-product" tabindex="-1">Editing a product <a class="header-anchor" href="#editing-a-product" aria-label="Permalink to &quot;Editing a product&quot;">​</a></h3><p>Open the product, edit, save. If someone saved the same product in the meantime, your save is refused: reload the page and make your change again.</p><p>Each save is sent automatically to the product&#39;s back-office if it is integrated.</p><h3 id="sync-status" tabindex="-1">Sync status <a class="header-anchor" href="#sync-status" aria-label="Permalink to &quot;Sync status&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Synced</td><td>The back-office has received the latest version of the product.</td></tr><tr><td>Pending</td><td>A send is in progress or will be retried.</td></tr><tr><td>Desynchronized</td><td>Sends failed after the number of attempts set in the <a href="./settings.html">configuration</a>. The CEO and the product&#39;s teams are alerted.</td></tr><tr><td>Not integrated</td><td>The back-office doesn&#39;t receive the product yet: reconcile by hand.</td></tr></tbody></table><p>When a product is desynchronized, check with the product&#39;s team that its back-office responds, then <strong>Resynchronize</strong> from the <strong>API integration</strong> page.</p><h2 id="integrating-a-product" tabindex="-1">Integrating a product <a class="header-anchor" href="#integrating-a-product" aria-label="Permalink to &quot;Integrating a product&quot;">​</a></h2><p>For the CEO only, from the product page. The technical details to pass on to the product&#39;s team are in <a href="./../integration/overview.html">Technical integration</a>.</p><h3 id="sso-integration" tabindex="-1">SSO integration <a class="header-anchor" href="#sso-integration" aria-label="Permalink to &quot;SSO integration&quot;">​</a></h3><p>Lets M&#39;City accounts open the product&#39;s back-office with their account.</p><ol><li>Product page → <strong>SSO integration</strong>.</li><li>Enter the <strong>redirect URIs</strong> given by the product&#39;s team (HTTPS, one per line, 5 at most) and, if it has one, the <strong>back-channel logout URI</strong>.</li><li><strong>Create the client</strong>.</li><li>Copy the <strong>client secret</strong>: it is shown only once. Pass it on to the product&#39;s team through a safe channel, with the client ID and the discovery URL shown on the page.</li></ol><p><strong>Regenerate the secret</strong> invalidates it at once: the back-office signs nobody in until it has the new one.</p><h3 id="api-integration" tabindex="-1">API integration <a class="header-anchor" href="#api-integration" aria-label="Permalink to &quot;API integration&quot;">​</a></h3><p>Lets the back-office read and update its product page, report its indicators, and receive every change to the product.</p><ol><li>Product page → <strong>API integration</strong>.</li><li><strong>Generate the token</strong> (service token), copy it (shown only once) and pass it on through a safe channel.</li><li>Enter the <strong>Webhook URL</strong> given by the product&#39;s team and save: the <strong>webhook secret</strong> is created and shown only once; pass it on too.</li><li>Choose the indicator <strong>reporting mode</strong>: sent by the product (API), polled hourly by M&#39;City, or the configuration&#39;s default.</li></ol><p>The page also shows the sync state, the latest exchanges, and two actions: <strong>Resynchronize</strong> (sends the product again) and <strong>Poll now</strong> (collects the indicators in polling mode).</p><p>Regenerating the token or the webhook secret invalidates the old one at once.</p>',30)])])}const u=e(r,[["render",i]]);export{p as __pageData,u as default};
